mapper.select:
select coalesce(sum(amount), 0)
from oa_fixed_asset_quota_ledger
where shop_dept_id = #{shopDeptId}
  and quota_year = #{quotaYear}
  and movement_type in ('normal_submit', 'advance_future_months')

mapper.insert:
insert into oa_fixed_asset_quota_ledger (
    repair_id, shop_dept_id, quota_year, movement_type, amount,
    create_by, create_time, remark
) values (
    #{repairId}, #{shopDeptId}, #{quotaYear}, #{movementType}, #{amount},
    #{createBy}, sysdate(), #{remark}
)
